(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-581":{scenario:{company:"Sao Mai Bottling Works",supervisor:{name:"Vũ Thành Nam",role:{vi:"Trưởng nhóm Tự động hóa",en:"Automation Team Lead"}},ref_code:"MOC-6620",title:{vi:"Đúng kiểu tín hiệu. Đúng thang đo. Không ép liên động.",en:"Right signal type. Right scaling. Never force an interlock."},brief:{vi:"Sau khi thay bộ truyền mức LT-301 của bồn siro (dải 0-6500 mm, tín hiệu 4-20 mA), màn hình HMI báo mức cao bất thường và liên động mức cao cắt bơm sớm. Đo vòng bằng thiết bị hiệu chuẩn được 11.2 mA. Đối chiếu cấu hình PLC nháp trong hồ sơ MOC-6620, sửa kiểu kênh đầu vào tương tự và giá trị mức đúng (mm), rồi lập báo cáo có căn cứ.",en:"After replacing level transmitter LT-301 on the syrup tank (range 0-6500 mm, 4-20 mA signal), the HMI shows an abnormally high level and the high-level interlock trips the pump early. A loop calibrator reads 11.2 mA. Check the draft PLC configuration in MOC-6620, correct the analogue input channel type and the true level (mm), then write an evidence-based report."},reference_title:{vi:"Hồ sơ quản lý thay đổi và bảng thiết bị đo đã duyệt · MOC-6620",en:"Approved change record and instrument index · MOC-6620"},fields:[{id:"AI_TYPE",label:{vi:"Kiểu kênh đầu vào tương tự",en:"Analogue input channel type"},initial:"0-20MA",expected:"4-20MA",choices:["0-20MA","4-20MA","0-10V"],reference:"Bảng thiết bị đo LT-301",hint:{vi:"Bộ truyền 2 dây cấp nguồn vòng luôn có dòng nền; kiểu kênh phải khớp tín hiệu ghi trên bảng dữ liệu.",en:"A 2-wire loop-powered transmitter always has a live zero; the channel type must match its datasheet signal."}},{id:"LEVEL_MM",label:{vi:"Mức bồn đúng tại 11.2 mA (mm)",en:"True tank level at 11.2 mA (mm)"},initial:"3640",expected:"2925",reference:"Biên bản đo vòng LT-301",ref_value:{vi:"Dải đo 0-6500 mm ứng với 4-20 mA; dòng đo được 11.2 mA",en:"Range 0-6500 mm maps to 4-20 mA; measured current 11.2 mA"},hint:{vi:"Trừ dòng nền 4 mA trước khi chia cho khoảng 16 mA rồi nhân với dải đo.",en:"Subtract the 4 mA live zero before dividing by the 16 mA span and multiplying by the range."}}],sop32:{vi:"Giá trị kỹ thuật = (dòng đo - 4 mA) / 16 mA x (cận trên - cận dưới) + cận dưới. Kênh tương tự phải cấu hình đúng kiểu tín hiệu ghi trên bảng thiết bị đo.",en:"Engineering value = (measured current - 4 mA) / 16 mA x (upper - lower range) + lower range. The analogue channel must match the signal type in the instrument index."},context:{label:"PLC ENGINEERING / MOC-6620",metrics:[{label:{vi:"Dải đo LT-301",en:"LT-301 range"},value:"0-6500 mm"},{label:{vi:"Dòng vòng đo được",en:"Measured loop current"},value:"11.2 mA"},{label:{vi:"Mức HMI hiển thị",en:"HMI level reading"},value:"3640 mm"}]},terminal:{system:"plc-eng",settable:["AI_TYPE","LEVEL_MM"],commands:[{cmd:"status",out:{vi:"PLC đang RUN; rack 1 khe 4 kênh 3 (LT-301) cấu hình AI_TYPE=0-20MA; HMI hiển thị LEVEL_MM=3640",en:"PLC in RUN; rack 1 slot 4 channel 3 (LT-301) configured AI_TYPE=0-20MA; HMI shows LEVEL_MM=3640"}},{cmd:"cat lt301_datasheet.txt",out:{vi:"Bộ truyền mức radar 2 dây, cấp nguồn vòng, ngõ ra 4-20 mA, dải 0-6500 mm; báo lỗi theo NAMUR NE 43: ≤ 3.6 mA hoặc ≥ 21 mA",en:"2-wire loop-powered radar level transmitter, 4-20 mA output, range 0-6500 mm; NAMUR NE 43 failure signal ≤ 3.6 mA or ≥ 21 mA"}},{cmd:"loopcal lt301",out:{vi:"Dòng vòng đo tại hộp nối JB-03: 11.20 mA, ổn định, không nhiễu",en:"Loop current at junction box JB-03: 11.20 mA, stable, no noise"}},{cmd:"cat moc6620.txt",out:{vi:"MOC-6620: thay bộ truyền 4 dây 0-20 mA cũ bằng loại 2 dây 4-20 mA; mục cập nhật cấu hình PLC chưa ký xác nhận",en:"MOC-6620: old 4-wire 0-20 mA transmitter replaced with 2-wire 4-20 mA type; PLC configuration update item not signed off"}},{cmd:"dipstick t301",out:{vi:"Đo thước nhúng thủ công: mức khoảng 2.9 m, thấp hơn nhiều so với HMI",en:"Manual dipstick: level about 2.9 m, well below the HMI reading"}}]},crisis:{vi:"Trưởng ca nhắn: “Liên động mức cao LAHH-301 cứ cắt bơm vô cớ, anh force bit về 0 cho chạy hết ca đi, mai sửa cấu hình sau, không ai kiểm tra đâu.”",en:"The shift leader messages: “The LAHH-301 high-level interlock keeps tripping the pump for nothing, force the bit to 0 so we finish the shift, fix the config tomorrow, nobody checks.”"},options:{safe:{vi:"Từ chối force liên động; sửa cấu hình qua MOC có phê duyệt, nếu cần bypass tạm thì làm giấy phép kèm biện pháp bù, báo trưởng ca và bộ phận an toàn.",en:"Refuse to force the interlock; fix the configuration under an approved MOC, and if a temporary bypass is needed, use a bypass permit with compensating measures and inform the shift and safety leads."},shortcut:{vi:"Force bit LAHH-301 về 0 để chạy hết ca rồi gỡ force vào sáng mai.",en:"Force the LAHH-301 bit to 0 for the rest of the shift and remove it tomorrow morning."},wait:{vi:"Không can thiệp, để vận hành tự xử lý các lần cắt bơm.",en:"Do nothing and let operations deal with the pump trips."}},questions:{vi:["Vì sao cấu hình 0-20MA làm HMI hiển thị 3640 mm trong khi mức thật là 2925 mm? Lỗi này ảnh hưởng điểm cắt liên động ra sao?","Quy trình nào cho phép bỏ qua liên động an toàn một cách hợp lệ, và vì sao force bit tùy tiện là nguy hiểm?"],en:["Why does the 0-20MA setting make the HMI show 3640 mm when the true level is 2925 mm? How does this shift the interlock trip point?","What procedure allows a safety interlock bypass legitimately, and why is forcing a bit casually dangerous?"]},hints:{vi:["Đặt cấu hình kênh cạnh bảng dữ liệu bộ truyền mới trong hồ sơ MOC.","Áp dụng SOP mục 3.2: dòng nền 4 mA tương ứng 0 mm, khoảng 16 mA tương ứng toàn dải 6500 mm.","Đọc lại SOP mục 4.2: không force, không bypass liên động khi chưa có giấy phép và biện pháp bù."],en:["Place the channel configuration next to the new transmitter datasheet in the MOC file.","Apply SOP 3.2: the 4 mA live zero means 0 mm and the 16 mA span covers the full 6500 mm.","Re-read SOP 4.2: never force or bypass an interlock without a permit and compensating measures."]}},learning:{summary:{vi:"Kỹ sư Tự động hóa và Lập trình PLC/SCADA thiết kế, lập trình, chạy thử và duy trì hệ thống điều khiển nhà máy: PLC, HMI, SCADA, mạng công nghiệp và các vòng đo lường, liên động an toàn. Mục tiêu là dây chuyền vận hành ổn định, an toàn và có dữ liệu tin cậy. Công việc đòi hỏi hiểu quá trình công nghệ, điện, đo lường, kỷ luật quản lý thay đổi và an ninh mạng công nghiệp.",en:"An Industrial Automation Engineer designs, programs, commissions and maintains plant control systems: PLCs, HMIs, SCADA, industrial networks, instrument loops and safety interlocks. The goal is stable, safe production with trustworthy data. The role requires understanding of the process, electrical and instrumentation work, strict change management discipline and industrial cybersecurity."},responsibilities:{vi:["Lập trình PLC theo IEC 61131-3, xây dựng màn hình HMI, SCADA và cơ sở dữ liệu thẻ.","Cấu hình vào ra, thang đo tín hiệu, mạng công nghiệp và đồng bộ thời gian.","Chạy thử vòng đo (loop check), FAT, SAT và bàn giao tài liệu cho vận hành.","Quản lý thay đổi phần mềm điều khiển, sao lưu phiên bản và kiểm soát force, bypass.","Xử lý sự cố điều khiển, tối ưu vòng PID và hệ thống cảnh báo."],en:["Program PLCs per IEC 61131-3 and build HMI, SCADA screens and tag databases.","Configure I/O, signal scaling, industrial networks and time synchronisation.","Perform loop checks, FAT and SAT and hand over documentation to operations.","Manage control software changes, version backups and force or bypass control.","Troubleshoot control faults and tune PID loops and alarm systems."]},competencies:[{name:{vi:"Lập trình PLC",en:"PLC programming"},desc:{vi:"Viết chương trình rõ ràng bằng ngôn ngữ thang, khối chức năng, văn bản cấu trúc và tái sử dụng khối.",en:"Write clear ladder, function block and structured text code with reusable blocks."}},{name:{vi:"Đo lường và tín hiệu",en:"Instrumentation and signals"},desc:{vi:"Hiểu 4-20 mA, HART, cấp nguồn vòng, thang đo và tín hiệu báo lỗi của thiết bị đo.",en:"Understand 4-20 mA, HART, loop power, scaling and instrument failure signals."}},{name:{vi:"An toàn chức năng",en:"Functional safety"},desc:{vi:"Phân biệt hệ thống điều khiển cơ bản với hệ thống an toàn và quản lý bypass đúng quy trình.",en:"Separate basic control from safety systems and manage bypasses by procedure."}},{name:{vi:"Mạng và an ninh OT",en:"OT networks and security"},desc:{vi:"Thiết kế phân vùng mạng, kiểm soát truy cập và sao lưu theo tiếp cận IEC 62443.",en:"Design network zones, access control and backups following IEC 62443."}},{name:{vi:"Chạy thử và xử lý sự cố",en:"Commissioning and troubleshooting"},desc:{vi:"Kiểm tra từng vòng từ hiện trường đến HMI, khoanh vùng lỗi nhanh và ghi nhận đầy đủ.",en:"Check every loop from field to HMI, isolate faults quickly and record everything."}}],knowledge:{vi:["IEC 61131-3 về ngôn ngữ lập trình PLC.","IEC 61508 và IEC 61511 về an toàn chức năng cho hệ thống điều khiển quá trình.","Khuyến nghị NAMUR NE 43 về mức dòng báo lỗi của tín hiệu 4-20 mA.","ISA-18.2 về quản lý hệ thống cảnh báo; ISA-88 về điều khiển mẻ.","ISA/IEC 62443 về an ninh mạng hệ thống tự động hóa công nghiệp."],en:["IEC 61131-3 on PLC programming languages.","IEC 61508 and IEC 61511 on functional safety for process control systems.","NAMUR NE 43 recommendation on failure current levels for 4-20 mA signals.","ISA-18.2 on alarm management; ISA-88 on batch control.","ISA/IEC 62443 on cybersecurity of industrial automation systems."]},tools:["Phần mềm lập trình PLC","Phần mềm SCADA/HMI","Thiết bị hiệu chuẩn vòng dòng","Bộ cấu hình thiết bị HART","Máy phân tích mạng công nghiệp"],kpis:{vi:["Thời gian dừng máy do lỗi điều khiển mỗi tháng.","Tỷ lệ thay đổi phần mềm đi qua MOC và có sao lưu.","Số force, bypass đang tồn tại quá hạn (mục tiêu bằng 0).","Số cảnh báo trên mỗi người vận hành mỗi giờ."],en:["Monthly downtime caused by control faults.","Share of software changes done under MOC with backups.","Overdue active forces and bypasses (target zero).","Alarms per operator per hour."]},day:[{time:"07:45",vi:"Kiểm tra danh sách force, bypass và cảnh báo tồn đọng từ ca đêm.",en:"Check the list of forces, bypasses and standing alarms from the night shift."},{time:"09:00",vi:"Đo vòng thiết bị mới thay theo MOC, đối chiếu thang đo với bảng thiết bị.",en:"Loop-check newly replaced instruments under MOC and match scaling to the index."},{time:"11:00",vi:"Sửa logic khởi động bơm, mô phỏng trên máy tính trước khi nạp xuống PLC.",en:"Modify pump start logic and simulate offline before downloading to the PLC."},{time:"14:00",vi:"Tinh chỉnh vòng PID nhiệt độ, ghi lại thông số trước và sau.",en:"Tune a temperature PID loop and record before and after parameters."},{time:"16:30",vi:"Sao lưu chương trình, cập nhật nhật ký thay đổi và bàn giao ca.",en:"Back up programs, update the change log and hand over to the next shift."}],mistakes:{vi:["Cấu hình kênh 0-20 mA cho bộ truyền 4-20 mA khiến mọi giá trị bị sai lệch.","Force bit hoặc bypass liên động để chạy tạm rồi quên gỡ.","Nạp chương trình trực tiếp khi máy chạy mà không sao lưu và không qua MOC."],en:["Configuring a 0-20 mA channel for a 4-20 mA transmitter, skewing every reading.","Forcing a bit or bypassing an interlock temporarily and forgetting to remove it.","Downloading code online to a running machine without a backup or MOC."]},career:[{vi:"Kỹ thuật viên điện - tự động hóa",en:"Electrical and automation technician"},{vi:"Kỹ sư tự động hóa PLC/SCADA",en:"PLC/SCADA automation engineer"},{vi:"Kỹ sư trưởng hệ thống điều khiển",en:"Lead control systems engineer"},{vi:"Trưởng phòng tự động hóa và OT",en:"Head of automation and OT"}],glossary:[{term:"Live zero",vi:"Mức dòng nền 4 mA đại diện điểm 0 của thang đo, giúp phân biệt mất tín hiệu với giá trị 0.",en:"The 4 mA base current representing zero, which separates signal loss from a true zero."},{term:"Loop check",vi:"Kiểm tra từng vòng đo từ thiết bị hiện trường tới PLC và HMI trước khi vận hành.",en:"Checking each loop from the field device to the PLC and HMI before operation."},{term:"Interlock",vi:"Logic liên động tự động dừng hoặc chặn thiết bị khi điều kiện không an toàn.",en:"Logic that automatically stops or blocks equipment under unsafe conditions."},{term:"MOC",vi:"Quản lý thay đổi, đánh giá rủi ro và phê duyệt trước khi sửa thiết bị, phần mềm, quy trình.",en:"Management of change, assessing risk and approving before modifying equipment, software or procedures."},{term:"Force",vi:"Ép trạng thái vào ra hoặc bit trong PLC bất kể logic chương trình, phải được kiểm soát chặt.",en:"Overriding an I/O point or bit in the PLC regardless of logic, which must be tightly controlled."}],quiz:[{q:{vi:"Bộ truyền áp suất dải 0-10 bar, tín hiệu 4-20 mA, đang ra 8 mA. Áp suất là bao nhiêu?",en:"A 0-10 bar pressure transmitter with 4-20 mA output reads 8 mA. What is the pressure?"},options:{vi:["4.0 bar","2.5 bar","5.0 bar","8.0 bar"],en:["4.0 bar","2.5 bar","5.0 bar","8.0 bar"]},answer:1,explain:{vi:"Áp suất = (8 - 4) / 16 x 10 = 2.5 bar; dùng 8/20 x 10 sẽ ra sai 4.0 bar.",en:"Pressure = (8 - 4) / 16 x 10 = 2.5 bar; using 8/20 x 10 gives the wrong 4.0 bar."}},{q:{vi:"Theo NAMUR NE 43, dòng 3.4 mA từ bộ truyền 4-20 mA nghĩa là gì?",en:"Under NAMUR NE 43, what does 3.4 mA from a 4-20 mA transmitter mean?"},options:{vi:["Giá trị bằng 0","Giá trị âm hợp lệ","Tín hiệu đang được hiệu chuẩn","Báo lỗi thiết bị hoặc đứt vòng"],en:["Zero value","A valid negative value","Calibration in progress","Device fault or broken loop"]},answer:3,explain:{vi:"Dòng ≤ 3.6 mA nằm trong vùng báo lỗi, PLC phải xử lý như tín hiệu hỏng.",en:"A current ≤ 3.6 mA is in the failure band and the PLC must treat it as a bad signal."}},{q:{vi:"Trưởng ca yêu cầu force liên động an toàn để chạy hết ca. Bạn làm gì?",en:"The shift leader asks you to force a safety interlock to finish the shift. What do you do?"},options:{vi:["Từ chối, xử lý nguyên nhân qua MOC hoặc làm giấy phép bypass có biện pháp bù","Force và ghi chú để mai gỡ","Tắt cảnh báo trên HMI","Đổi điểm đặt liên động lên cao hơn"],en:["Refuse, fix the cause via MOC or use a bypass permit with compensating measures","Force it and leave a note to remove tomorrow","Silence the alarm on the HMI","Raise the interlock setpoint"]},answer:0,explain:{vi:"Liên động bảo vệ người và thiết bị; mọi bypass phải có phê duyệt, thời hạn và biện pháp bù.",en:"Interlocks protect people and equipment; any bypass needs approval, a time limit and compensating measures."}},{q:{vi:"Chuẩn IEC 61131-3 quy định nội dung gì?",en:"What does IEC 61131-3 define?"},options:{vi:["Mức an toàn SIL","Cáp mạng công nghiệp","Ngôn ngữ lập trình PLC","An ninh mạng OT"],en:["Safety integrity levels","Industrial network cabling","PLC programming languages","OT cybersecurity"]},answer:2,explain:{vi:"IEC 61131-3 định nghĩa các ngôn ngữ như LD, FBD, ST, SFC cho bộ điều khiển lập trình.",en:"IEC 61131-3 defines languages such as LD, FBD, ST and SFC for programmable controllers."}}],tools_en:["PLC programming software","SCADA/HMI software","Current loop calibrator","HART device configurator","Industrial network analyzer"]}}})})(window.KKR);
